import { NextFunction, Request, Response } from 'express';
import { classifyError, ErrorCategory } from '../../../application/errors/ErrorClassification';
import { BadRequestError } from '../RequestParsing';

const STATUS_BY_CATEGORY: Record<ErrorCategory, number> = {
  validation: 422,
  not_found: 404,
  conflict: 409,
};

function isMalformedJson(error: unknown): boolean {
  return typeof error === 'object' && error !== null && 'type' in error && error.type === 'entity.parse.failed';
}

export function errorHandlerMiddleware(error: unknown, _req: Request, res: Response, _next: NextFunction): void {
  if (error instanceof BadRequestError) {
    res.status(400).json({ error: error.message });
    return;
  }
  if (isMalformedJson(error)) {
    res.status(400).json({ error: 'Malformed JSON body' });
    return;
  }

  const description = classifyError(error);
  if (description !== null) {
    res.status(STATUS_BY_CATEGORY[description.category]).json({ error: description.message });
    return;
  }

  console.error(error);
  res.status(500).json({ error: 'Internal server error' });
}

=====SOURCE-END=====

